import csv

SRC = "/work/workspace/documents/bank_checking_2024-12_to_2026-01.csv"
OUT = "/work/workspace/deliverable/classification.csv"

def classify(d, desc, amt):
    s = desc.upper()
    year = int(d.split("-")[0])
    if "TESSARO" in s and "CREDIT" in s:
        if year == 2024:
            return ("prior_year", "", "Invoice 1041 received 12/27/2024 - prior-year income (cash method); Tessaro 2025 1099-NEC ($9,400) matches 2025 deposits only")
        return ("business_income", "1", "Direct ACH from Tessaro; not part of 1099-K; 2025 receipts total $9,400 = Tessaro 1099-NEC box 1")
    if "PAYHUB" in s:
        return ("business_income", "1", "Payout is NET of ~2.9% processor fee; gross on 1099-K ($41,350) goes to line 1 once (includes Beacon/Orchard NEC amounts); fee to line 10")
    if "LARKSPUR" in s:
        return ("other_schedule", "", "W-2 wages (W-2 box 1 $24,800) - Form 1040 line 1, not Schedule C")
    if "HISCOX" in s:
        return ("business_expense", "15", "Professional liability insurance")
    if "T-MOBILE" in s:
        return ("business_expense", "25", "Mixed personal/business; line 25 carries 80% ASSUMPTION pending client answer; 12 x $85 = $1,020/yr")
    if "SPECTRUM" in s:
        return ("business_expense", "25", "Mixed personal/business; line 25 carries 80% ASSUMPTION pending client answer; 12 x $70 = $840/yr")
    if "FIGMA" in s or "ADOBE" in s:
        return ("business_expense", "27a", "Business software subscription (line 27a per Sch C instr. excerpt)")
    if "NETFLIX" in s:
        return ("personal", "", "Personal entertainment - IRC 262")
    if "ORANGETHEORY" in s:
        return ("personal", "", "Personal gym - IRC 262")
    if "H-E-B" in s:
        if year == 2024:
            return ("personal", "", "Personal groceries, Dec 2024 (outside tax year) - IRC 262")
        return ("personal", "", "Personal groceries - IRC 262")
    if "RENT" in s and "ZELLE" in s:
        return ("personal", "", "Apartment rent - IRC 262; no qualifying home office in file")
    if "IRS USATAXPYMT" in s:
        return ("tax_payment", "", "Estimated tax payment - applied on Form 1040; not deductible on Sch C")
    if "CAPITAL FACTORY" in s:
        return ("business_expense", "20b", "Coworking membership rent, May-Dec (8 x $350); commute TO it stays nondeductible")
    if "BLUE CROSS" in s:
        return ("other_schedule", "", "Health insurance - self-employed health insurance deduction, Schedule 1 line 17 (NOT line 15)")
    if "SOUTHWEST AIR 118" in s and "DEN" in s:
        return ("personal", "", "Likely personal wedding trip (wedding gift Venmo'd next day; no Denver client trips in mileage log) - PENDING client confirmation")
    if "WEDDING GIFT" in s:
        return ("personal", "", "Personal gift - IRC 262")
    if "SOUTHWEST AIR 526" in s and "SFO" in s:
        return ("business_expense", "24a", "Airfare to DesignWeek SF business trip")
    if "HOTEL ZEPHYR" in s:
        return ("business_expense", "24a", "Lodging, DesignWeek SF business trip")
    if "DESIGNWEEK" in s:
        return ("business_expense", "27a", "Conference registration - professional development on line 27a")
    if "MARINA DELI" in s:
        return ("business_expense", "24b", "Meal while away from home on business; 50% limit -> $32.00 of $64.00 on line 24b")
    if "TARTINE" in s:
        return ("business_expense", "24b", "Meal while away from home on business; 50% limit -> $63.00 of $126.00 on line 24b (confirm business trip days)")
    if "MACBOOK" in s:
        return ("business_expense", "27a", "MacBook Pro $2,149 <= $2,500/invoice - de minimis safe harbor election (Reg. 1.263(a)-1(f)) expensed on line 27a, election statement to attach; confirm 100% business use")
    return ("other", "", "UNCLASSIFIED - review")

rows_out = []
totals = {}
with open(SRC, newline="") as f:
    for r in csv.DictReader(f):
        cls, line, note = classify(r["date"], r["description"], float(r["amount"]))
        rows_out.append({"date": r["date"], "description": r["description"], "amount": r["amount"],
                         "classification": cls, "schedule_c_line": line, "note": note})
        totals.setdefault(cls, []).append(float(r["amount"]))

with open(OUT, "w", newline="") as f:
    w = csv.DictWriter(f, fieldnames=["date", "description", "amount", "classification", "schedule_c_line", "note"])
    w.writeheader()
    w.writerows(rows_out)

# ---- verification computations ----
def s(pred):
    return round(sum(float(r["amount"]) for r in rows_out if pred(r)), 2)

payhub = s(lambda r: "PAYHUB" in r["description"])
tess25 = s(lambda r: "TESSARO" in r["description"] and r["date"].startswith("2025"))
tess24 = s(lambda r: "TESSARO" in r["description"] and r["date"].startswith("2024"))
lark   = s(lambda r: "LARKSPUR" in r["description"])
gross_k = 41350.00
fee = round(gross_k - payhub, 2)
print("PayHub deposits net:", payhub, " | 1099-K gross:", gross_k, " | implied fee:", fee,
      " | fee%:", round(fee / gross_k, 6))
print("Feb check 1866.68*0.971 =", round(1866.68 * 0.971, 2), "vs deposit 1812.55")
print("Tessaro 2025 ACH:", tess25, "(= NEC 9,400?) | Tessaro 2024:", tess24)
print("Larkspur deposits:", lark, "(W-2 box1 24,800 gross, pretax/tax diff)")
line1 = round(gross_k + tess25, 2)
line9 = round(1428 * 0.70, 2)
line10 = fee
line15 = s(lambda r: "HISCOX" in r["description"])
line20b = s(lambda r: "CAPITAL FACTORY" in r["description"])
line24a = round(412.00 + 618.00, 2)
line24b = round((64.00 + 126.00) * 0.50, 2)
phone = s(lambda r: "T-MOBILE" in r["description"]); net = s(lambda r: "SPECTRUM" in r["description"])
line25 = round((phone + net) * 0.80, 2)
figma = s(lambda r: "FIGMA" in r["description"]); adobe = s(lambda r: "ADOBE" in r["description"])
mac = 2149.00; conf = 650.00
line27a = round(figma + adobe + mac + conf, 2)
exp = round(line9 + line10 + line15 + line20b + line24a + line24b + line25 + line27a, 2)
net_profit = round(line1 - exp, 2)
print("phone/yr", phone, "net/yr", net, "figma", figma, "adobe", adobe)
print("lines:", dict(l1=line1, l9=line9, l10=line10, l15=line15, l20b=line20b,
                     l24a=line24a, l24b=line24b, l25=line25, l27a=line27a, l28=exp, l31=net_profit))
ne = round(net_profit * 0.9235, 2)
ss_test = 24800.00 + ne
se_tax = round(ne * 0.153, 2)
half = round(se_tax / 2, 2)
print("SE: net earnings", ne, "| W2SS+NE", ss_test, "< 176,100?", ss_test <= 176100,
      "| SE tax", se_tax, "| half", half)
# not_on_schedule_c / personal summaries
rent = s(lambda r: "RENT" in r["description"]); heb25 = s(lambda r: "H-E-B" in r["description"] and r["date"].startswith("2025"))
nfx = s(lambda r: "NETFLIX" in r["description"]); gym = s(lambda r: "ORANGETHEORY" in r["description"])
es = s(lambda r: "USATAXPYMT" in r["description"]); bcbs = s(lambda r: "BLUE CROSS" in r["description"])
print("rent", abs(rent), "heb25", abs(heb25), "netflix", abs(nfx), "gym", abs(gym),
      "est-tax", abs(es), "bcbs", abs(bcbs))
# reconcile statement header
beg = 4210.33; end = 32955.15
credits = sum(float(r["amount"]) for r in rows_out if float(r["amount"]) > 0)
debits = sum(float(r["amount"]) for r in rows_out if float(r["amount"]) < 0)
print("credits", round(credits, 2), "vs 72053.65 | debits", round(debits, 2), "vs -43308.83")
print("beg+cr-dr =", round(beg + credits + debits, 2), "vs", end)
print("rows:", len(rows_out))
uncl = [r for r in rows_out if r["classification"] == "other"]
print("unclassified:", uncl)

